#!/usr/bin/env python3
"""Per-model delta prompts: the final prompts whose exact (task, variant, text) were NOT yet generated by that model.

usage: python scripts/make_delta.py <generations dir of one model> [--prompts data/prompts/prompts.jsonl] [--out file]
Re-generated prompts keep their gen_id, so the newer output overrides the older one when results are merged (later
gens_*.jsonl files win in run_execution.load_gens)."""
import argparse, json
from pathlib import Path

ap = argparse.ArgumentParser()
ap.add_argument("model_dir")
ap.add_argument("--prompts", default="data/prompts/prompts.jsonl")
ap.add_argument("--out", default="")
a = ap.parse_args()
done = set()
for f in sorted(Path(a.model_dir).glob("gens_*.jsonl")):
    for l in f.read_text(encoding="utf-8").split("\n"):
        if l.strip():
            r = json.loads(l)
            if r["condition"] == "DIRECT":
                done.add((r["task_id"], r["variant"], r["prompt_text"]))
P = [json.loads(l) for l in Path(a.prompts).read_text(encoding="utf-8").split("\n") if l.strip()]
delta = [p for p in P if (p["task_id"], p["variant"], p["text"]) not in done]
out = Path(a.out or f"data/prompts/prompts_delta_{Path(a.model_dir).name}.jsonl")
with open(out, "w", encoding="utf-8", newline="\n") as f:
    for p in delta:
        f.write(json.dumps(p, ensure_ascii=False) + "\n")
print(f"{Path(a.model_dir).name}: {len(delta)} of {len(P)} prompts still to generate -> {out}")
